import os
import hashlib
import hmac
import time
import json
import re
from urllib.parse import unquote, urlparse, parse_qs
from pathlib import Path, PurePosixPath
from typing import Optional, Dict, Tuple
import secrets
import logging

logger = logging.getLogger(__name__)

# Security configuration
SESSION_SECRET = os.environ.get('SESSION_SECRET', secrets.token_hex(32))
DOCUMENT_ROOT = os.path.realpath(os.environ.get('DOCUMENT_ROOT', '/srv/documents'))
MAX_PATH_LENGTH = 4096
ALLOWED_EXTENSIONS = {'.pdf', '.txt', '.md', '.html', '.json', '.csv'}


class SessionManager:
    """Manages authenticated sessions with HMAC-based tokens."""

    def __init__(self, secret: str):
        self._secret = secret.encode('utf-8')
        self._revoked: set = set()

    def create_session(self, user_id: str, role: str) -> str:
        payload = json.dumps({
            'sub': user_id,
            'role': role,
            'iat': int(time.time()),
            'exp': int(time.time()) + 3600,
            'jti': secrets.token_hex(16)
        })
        sig = hmac.new(self._secret, payload.encode(), hashlib.sha256).hexdigest()
        return f"{payload}|{sig}"

    def validate_session(self, token: str) -> Optional[Dict]:
        try:
            parts = token.rsplit('|', 1)
            if len(parts) != 2:
                return None
            payload_str, signature = parts
            expected_sig = hmac.new(
                self._secret, payload_str.encode(), hashlib.sha256
            ).hexdigest()
            if not hmac.compare_digest(expected_sig, signature):
                return None
            payload = json.loads(payload_str)
            if payload.get('jti') in self._revoked:
                return None
            if time.time() > payload.get('exp', 0):
                return None
            return payload
        except (ValueError, json.JSONDecodeError):
            return None

    def revoke(self, jti: str):
        self._revoked.add(jti)


class AccessControl:
    """Role-based access control for document paths."""

    _ROLE_PERMISSIONS = {
        'admin': {'read', 'write', 'delete', 'list'},
        'editor': {'read', 'write', 'list'},
        'viewer': {'read', 'list'},
        'guest': {'read'}
    }

    _PATH_RESTRICTIONS = {
        'guest': ['/public/'],
        'viewer': ['/public/', '/shared/'],
        'editor': ['/public/', '/shared/', '/drafts/'],
        'admin': ['/']  # unrestricted
    }

    @classmethod
    def check_permission(cls, role: str, action: str, path: str) -> bool:
        permissions = cls._ROLE_PERMISSIONS.get(role, set())
        if action not in permissions:
            return False
        restrictions = cls._PATH_RESTRICTIONS.get(role, [])
        normalized_path = '/' + path.lstrip('/')
        return any(normalized_path.startswith(prefix) for prefix in restrictions)


class PathValidator:
    """Validates and sanitizes file paths to prevent directory traversal."""

    def __init__(self, document_root: str):
        self._root = document_root
        self._root_parts = Path(document_root).parts

    def _decode_path(self, raw_path: str) -> str:
        """Decode URL-encoded path components.

        Security note: We decode the path to handle legitimate URL encoding
        from browsers. The traversal check happens AFTER decoding.
        """
        decoded = unquote(raw_path)
        return decoded

    def _check_traversal_patterns(self, path: str) -> bool:
        """Check for common traversal patterns in the decoded path."""
        # Block null bytes
        if '\x00' in path:
            return False
        # Block obvious traversal sequences
        if '..' in path.split('/'):
            return False
        # Block backslash (Windows-style paths)
        if '\\' in path:
            return False
        return True

    def _validate_extension(self, path: str) -> bool:
        """Ensure file has an allowed extension."""
        ext = Path(path).suffix.lower()
        return ext in ALLOWED_EXTENSIONS

    def resolve_safe_path(self, user_path: str) -> Optional[str]:
        """Resolve a user-provided path to a safe absolute path.

        Returns None if the path is invalid or attempts traversal.
        """
        if not user_path or len(user_path) > MAX_PATH_LENGTH:
            return None

        # Step 1: Decode URL encoding
        decoded_path = self._decode_path(user_path)

        # Step 2: Check for traversal patterns
        if not self._check_traversal_patterns(decoded_path):
            logger.warning(f"Traversal pattern detected: {user_path[:100]}")
            return None

        # Step 3: Normalize path separators and remove leading slash
        clean_path = decoded_path.strip('/').replace('//', '/')

        # Step 4: Construct full path and resolve
        full_path = os.path.join(self._root, clean_path)
        resolved = os.path.realpath(full_path)

        # Step 5: Verify resolved path is under document root
        if not resolved.startswith(self._root):
            logger.warning(f"Path escape attempt: {user_path[:100]}")
            return None

        # Step 6: Validate extension
        if not self._validate_extension(resolved):
            return None

        return resolved


class DocumentService:
    """Main service handling document operations."""

    def __init__(self):
        self._session_mgr = SessionManager(SESSION_SECRET)
        self._path_validator = PathValidator(DOCUMENT_ROOT)
        self._access_log: list = []

    def _log_access(self, user: str, action: str, path: str, allowed: bool):
        self._access_log.append({
            'timestamp': time.time(),
            'user': user,
            'action': action,
            'path': path,
            'allowed': allowed
        })

    def handle_request(self, method: str, path: str, headers: Dict) -> Tuple[int, str]:
        """Process an incoming document request."""
        # Authenticate
        auth_header = headers.get('Authorization', '')
        if not auth_header.startswith('Bearer '):
            return (401, '{"error": "authentication required"}')

        token = auth_header[7:]
        session = self._session_mgr.validate_session(token)
        if not session:
            return (401, '{"error": "invalid or expired session"}')

        user_id = session['sub']
        role = session['role']

        # Map HTTP method to action
        action_map = {'GET': 'read', 'PUT': 'write', 'DELETE': 'delete'}
        action = action_map.get(method)
        if not action:
            return (405, '{"error": "method not allowed"}')

        # Resolve path
        safe_path = self._path_validator.resolve_safe_path(path)
        if not safe_path:
            return (400, '{"error": "invalid path"}')

        # Check access control
        relative_path = safe_path[len(self._root):]
        if not AccessControl.check_permission(role, action, relative_path):
            self._log_access(user_id, action, relative_path, False)
            return (403, '{"error": "access denied"}')

        self._log_access(user_id, action, relative_path, True)

        # Execute action
        if action == 'read':
            return self._read_document(safe_path)
        elif action == 'write':
            return (200, '{"status": "written"}')
        elif action == 'delete':
            return (200, '{"status": "deleted"}')

        return (500, '{"error": "internal error"}')

    def _read_document(self, path: str) -> Tuple[int, str]:
        try:
            if not os.path.isfile(path):
                return (404, '{"error": "not found"}')
            with open(path, 'r') as f:
                content = f.read(1024 * 1024)  # 1MB limit
            return (200, content)
        except (IOError, PermissionError):
            return (500, '{"error": "read error"}')


def create_app():
    """Factory function to create the document service."""
    return DocumentService()


if __name__ == '__main__':
